Here is the C++ implementation for both the Array-based and Singly Linked List-based systems without using any STL containers, along with the console outputs and clinical insights.

```cpp
#include <iostream>
#include <iomanip>
#include <string>
#include <chrono>
using namespace std;

struct Patient {
    string id, careType;
    int age, facility;
    double duration, baseCost, visitsPerYear, totalCost;
};

// --- PROGRAM 1: ARRAY IMPLEMENTATION ---
class ArraySystem {
    Patient* arr;
    int size, capacity;
public:
    ArraySystem(int cap = 3000) : size(0), capacity(cap) { arr = new Patient[capacity]; }
    ~ArraySystem() { delete[] arr; }
    void add(string id, int a, string c, double d, double b, double v, int f) {
        if (size < capacity) arr[size++] = {id, c, a, f, d, b, v, d * b * v};
    }
    void bubbleSortByCost() {
        for (int i = 0; i < size - 1; i++)
            for (int j = 0; j < size - i - 1; j++)
                if (arr[j].totalCost > arr[j + 1].totalCost) {
                    Patient temp = arr[j]; arr[j] = arr[j + 1]; arr[j + 1] = temp;
                }
    }
    int binarySearchByCost(double target) {
        int l = 0, r = size - 1;
        while (l <= r) {
            int m = l + (r - l) / 2;
            if (arr[m].totalCost == target) return m;
            if (arr[m].totalCost < target) l = m + 1; else r = m - 1;
        }
        return -1;
    }
};

// --- PROGRAM 2: SINGLY LINKED LIST IMPLEMENTATION ---
struct Node {
    Patient data;
    Node* next;
    Node(Patient p) : data(p), next(nullptr) {}
};

class LinkedListSystem {
    Node* head;
public:
    LinkedListSystem() : head(nullptr) {}
    void add(string id, int a, string c, double d, double b, double v, int f) {
        Node* n = new Node({id, c, a, f, d, b, v, d * b * v});
        n->next = head; head = n;
    }
    void bubbleSortByCost() {
        if (!head) return;
        bool swapped;
        do {
            swapped = false;
            Node* cur = head;
            while (cur->next) {
                if (cur->data.totalCost > cur->next->data.totalCost) {
                    Patient tmp = cur->data; cur->data = cur->next->data; cur->next->data = tmp;
                    swapped = true;
                }
                cur = cur->next;
            }
        } while (swapped);
    }
    Node* linearSearchCare(string care) {
        Node* cur = head;
        while (cur) { if (cur->data.careType == care) return cur; cur = cur->next; }
        return nullptr;
    }
};
```

